<script>
  document.addEventListener('DOMContentLoaded', function () {
    // Dropdown UX
    var dropdowns = Array.prototype.slice.call(document.querySelectorAll('.nav-dd'));
    dropdowns.forEach(function (dd) {
      var leaveTimer = null;
      dd.addEventListener('mouseleave', function () {
        leaveTimer = setTimeout(function () { dd.removeAttribute('open'); }, 250);
      });
      dd.addEventListener('mouseenter', function () {
        if (leaveTimer) { clearTimeout(leaveTimer); leaveTimer = null; }
      });
      dd.querySelectorAll('.dd-menu a').forEach(function (a) {
        a.addEventListener('click', function () { dd.removeAttribute('open'); });
      });
    });
    document.addEventListener('click', function (e) {
      dropdowns.forEach(function (dd) {
        if (dd.hasAttribute('open') && !dd.contains(e.target)) dd.removeAttribute('open');
      });
    });

    // Collapse / expand channel groups
    document.querySelectorAll('.channel-header').forEach(function (h) {
      h.addEventListener('click', function () {
        var group = h.parentElement;
        var wrap = group.querySelector('.reports-table-wrap');
        var collapsed = h.classList.toggle('collapsed');
        wrap.style.display = collapsed ? 'none' : '';
      });
    });

    // Filtering
    var groups = Array.prototype.slice.call(document.querySelectorAll('.channel-group'));
    var chips = Array.prototype.slice.call(document.querySelectorAll('.filter-chip'));
    var search = document.getElementById('search');
    var emptyState = document.getElementById('empty');
    var countEl = document.getElementById('count');
    var activePillar = 'all';

    function applyFilters() {
      var q = (search.value || '').trim().toLowerCase();
      var visibleGroups = 0, visibleRows = 0;

      groups.forEach(function (g) {
        var pillars = (g.getAttribute('data-pillars') || '').split(/\s+/);
        var pillarMatch = activePillar === 'all' || pillars.indexOf(activePillar) !== -1;

        var rows = g.querySelectorAll('tbody tr');
        var anyRowMatches = false;
        rows.forEach(function (r) {
          var text = r.textContent.toLowerCase();
          var rowMatch = q === '' || text.indexOf(q) !== -1;
          var show = pillarMatch && rowMatch;
          r.classList.toggle('row-hidden', !show);
          if (show) { anyRowMatches = true; visibleRows++; }
        });

        var headerText = g.querySelector('.channel-header').textContent.toLowerCase();
        var headerMatch = q === '' || headerText.indexOf(q) !== -1;
        var showGroup = pillarMatch && (anyRowMatches || (q !== '' && headerMatch));
        g.classList.toggle('hidden', !showGroup);
        if (showGroup) visibleGroups++;
      });

      emptyState.style.display = visibleGroups === 0 ? '' : 'none';
      countEl.textContent = visibleRows + ' report' + (visibleRows === 1 ? '' : 's') + ' across ' + visibleGroups + ' channel' + (visibleGroups === 1 ? '' : 's');
    }

    chips.forEach(function (c) {
      c.addEventListener('click', function () {
        chips.forEach(function (x) { x.classList.remove('active'); });
        c.classList.add('active');
        activePillar = c.getAttribute('data-pillar');
        applyFilters();
      });
    });
    search.addEventListener('input', applyFilters);
    document.getElementById('clear-filters').addEventListener('click', function (e) {
      e.preventDefault();
      search.value = '';
      activePillar = 'all';
      chips.forEach(function (x) { x.classList.toggle('active', x.getAttribute('data-pillar') === 'all'); });
      applyFilters();
    });

    applyFilters();
  });
</script>

