    --c-light-blue: #8DC8E8;
    --c-aqua: #B9DCD2;
    --c-lavender: #C5B4E3;

    --ms-blue: var(--c-med-blue);
    --ms-blue-dark: var(--c-dark-blue);
    --ms-blue-light: #E6F2FB;
    --ink: var(--c-dark-blue);
    --ink-soft: var(--c-n50);
    --line: var(--c-n15);
    --bg: var(--c-n05);
    --card: var(--c-white);
    --shadow: 0 1.6px 3.6px rgba(9,31,46,0.08), 0 0.3px 0.9px rgba(9,31,46,0.06);
