  box-shadow: 0 8px 24px rgba(9,31,46,0.35), 0 2px 6px rgba(9,31,46,0.2);
  display: inline-flex; align-items: center; gap: 10px;
  animation: fab-pulse 2.4s ease-in-out infinite;
}
.comment-fab::before { content: "✏️"; font-size: 1.1rem; }
.comment-fab:hover {
  background: var(--c-dark-blue);
  color: white;
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(9,31,46,0.45);
  animation: none;
}
.comment-fab .badge {
  background: var(--c-dark-blue); color: white;
  border-radius: 999px; padding: 2px 10px;
  font-size: 0.8rem; font-weight: 700;
  min-width: 22px; text-align: center;
}
.comment-fab:hover .badge { background: var(--c-teal); color: var(--c-dark-blue); }
@keyframes fab-pulse {
